import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.D5wUhsuj.js";const g=JSON.parse('{"title":"Docker Deployment Guide","description":"","frontmatter":{},"headers":[],"relativePath":"user_manual/DOCKER_en.md","filePath":"user_manual/DOCKER_en.md"}'),n={name:"user_manual/DOCKER_en.md"};function l(o,t,r,d,h,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="docker-deployment-guide" tabindex="-1">Docker Deployment Guide <a class="header-anchor" href="#docker-deployment-guide" aria-label="Permalink to &quot;Docker Deployment Guide&quot;">​</a></h1><blockquote><p>Version: 1.0.0 · <a href="/docs/user_manual/DOCKER">中文</a></p></blockquote><p>PhyAgentOS ships with a Docker-based quick deployment that requires no manual Python / Node.js setup. Together with the <a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/scripts/install.sh" target="_blank" rel="noreferrer"><code>scripts/install.sh</code></a> one-click script, you can build, initialize, and run in under a minute.</p><blockquote><p>Image base: <code>ghcr.io/astral-sh/uv:python3.12-bookworm-slim</code> (CPU, a few hundred MB)</p></blockquote><hr><h2 id="📦-what-s-in-the-image" tabindex="-1">📦 What&#39;s in the Image <a class="header-anchor" href="#📦-what-s-in-the-image" aria-label="Permalink to &quot;📦 What&#39;s in the Image&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">Python 3.12 runtime</td><td style="text-align:left;">All <code>pyproject.toml</code> deps installed via <code>uv</code></td></tr><tr><td style="text-align:left;"><code>paos</code> CLI</td><td style="text-align:left;">Registered as the entrypoint (<code>ENTRYPOINT</code>)</td></tr><tr><td style="text-align:left;">Node.js 20</td><td style="text-align:left;">Strictly builds the WhatsApp bridge from locked npm dependencies</td></tr><tr><td style="text-align:left;">Config directory</td><td style="text-align:left;"><code>/root/.PhyAgentOS</code> (persisted to the host via a volume mount)</td></tr><tr><td style="text-align:left;">Default service</td><td style="text-align:left;">Interactive CLI (<code>paos agent</code>); switchable to a long-running gateway</td></tr></tbody></table><p>The image does <strong>not</strong> include Dora CLI, concrete Forge Skills or nodes, GPU / CUDA, Isaac Sim, BEHAVIOR-1K, or other robot Runtime dependencies. The stock image runs the general Agent and its message-bus gateway; it does not provide a managed Forge Skill Runtime. Run that Runtime from a host-native PhyAgentOS installation following the <a href="/docs/en/02-user-manual#dora-cli-for-managed-skill-profiles">user manual</a>, or build a custom image containing Dora CLI v0.4.1 with <code>dora-message</code> v0.7.0 and every prerequisite of the selected Skill profile. Installing Dora only on the host does not make it visible inside the stock container.</p><blockquote><p><strong>About the gateway port</strong>: <code>paos gateway</code> is a message-bus service (Agent + channels + Cron + Heartbeat + Forge orchestration) that makes <strong>outbound connections only</strong> (LLM providers, Telegram/DingTalk, etc.) and does <strong>not</strong> bind an inbound port. <code>gateway.port</code> in <code>config.json</code> is currently shown only in the startup log and is not bound to a socket, so the container needs <strong>no</strong> <code>-p</code> port mapping.</p></blockquote><hr><h2 id="✅-prerequisites" tabindex="-1">✅ Prerequisites <a class="header-anchor" href="#✅-prerequisites" aria-label="Permalink to &quot;✅ Prerequisites&quot;">​</a></h2><ul><li><strong>Docker 20.10+</strong> (with the daemon running)</li><li>Optional: <strong>Docker Compose v2</strong> (if you use <code>docker-compose.yml</code>)</li></ul><p>Check your environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # confirm the daemon is up</span></span></code></pre></div><hr><h2 id="🚀-one-click-install-run" tabindex="-1">🚀 One-click install &amp; run <a class="header-anchor" href="#🚀-one-click-install-run" aria-label="Permalink to &quot;🚀 One-click install &amp; run&quot;">​</a></h2><blockquote><p>The <code>./scripts/install.sh</code> commands below are run from the <strong>repository root</strong>.</p></blockquote><p>Minimal flow, two commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Build the image + write the default config (first run)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Edit the config and add your LLM API key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    macOS / Linux:  vi ~/.PhyAgentOS/config.json</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    Put it under providers.&lt;name&gt;.apiKey</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Enter the interactive CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span></span></code></pre></div><h3 id="full-command-list" tabindex="-1">Full command list <a class="header-anchor" href="#full-command-list" aria-label="Permalink to &quot;Full command list&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>./scripts/install.sh</code></td><td style="text-align:left;">(default) build image + initialize config</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh build</code></td><td style="text-align:left;">build the image only</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh onboard</code></td><td style="text-align:left;">write the default config to <code>~/.PhyAgentOS/config.json</code> only</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh chat</code></td><td style="text-align:left;">interactive CLI (default service)</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh gateway</code></td><td style="text-align:left;">long-running gateway (message bus, outbound only, no inbound port)</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh status</code></td><td style="text-align:left;">show PhyAgentOS status</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh stop</code></td><td style="text-align:left;">stop the gateway container</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh logs</code></td><td style="text-align:left;">tail gateway logs</td></tr><tr><td style="text-align:left;"><code>./scripts/install.sh help</code></td><td style="text-align:left;">show help</td></tr></tbody></table><hr><h2 id="⚙️-configuration-environment" tabindex="-1">⚙️ Configuration &amp; environment <a class="header-anchor" href="#⚙️-configuration-environment" aria-label="Permalink to &quot;⚙️ Configuration &amp; environment&quot;">​</a></h2><h3 id="data-directory" tabindex="-1">Data directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data directory&quot;">​</a></h3><p>All config, workspace, and session history live on the host under <code>~/.PhyAgentOS</code>, injected into the container via a volume mount (<code>-v</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host ~/.PhyAgentOS  ⟷  Container /root/.PhyAgentOS</span></span></code></pre></div><p>So <strong>removing the image does not lose data</strong>; re-running the script restores everything.</p><h3 id="configurable-environment-variables" tabindex="-1">Configurable environment variables <a class="header-anchor" href="#configurable-environment-variables" aria-label="Permalink to &quot;Configurable environment variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PAOS_DATA_DIR</code></td><td style="text-align:left;"><code>~/.PhyAgentOS</code></td><td style="text-align:left;">Config &amp; workspace directory</td></tr></tbody></table><p>Example: start the gateway with a custom data directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAOS_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/data/paos</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./scripts/install.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span></span></code></pre></div><h3 id="api-key-configuration" tabindex="-1">API key configuration <a class="header-anchor" href="#api-key-configuration" aria-label="Permalink to &quot;API key configuration&quot;">​</a></h3><p>Both the interactive CLI and the gateway need an LLM provider API key. The install script writes a default config template during <code>onboard</code>; edit the <code>providers</code> section:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;openrouter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_API_KEY&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See <code>paos provider login</code> for supported providers and OAuth flows.</p><hr><h2 id="🧩-using-docker-compose" tabindex="-1">🧩 Using Docker Compose <a class="header-anchor" href="#🧩-using-docker-compose" aria-label="Permalink to &quot;🧩 Using Docker Compose&quot;">​</a></h2><p>The repo ships a <a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/docker-compose.yml" target="_blank" rel="noreferrer"><code>docker-compose.yml</code></a> for scenarios that need a persistent service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the gateway (background, auto-restart)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos-gateway</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos-gateway</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enter the interactive CLI (separate profile)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos-cli</span></span></code></pre></div><hr><h2 id="🔧-using-docker-directly-without-the-script" tabindex="-1">🔧 Using Docker directly (without the script) <a class="header-anchor" href="#🔧-using-docker-directly-without-the-script" aria-label="Permalink to &quot;🔧 Using Docker directly (without the script)&quot;">​</a></h2><p>For full manual control (<code>docker build</code> must be run from the <strong>repository root</strong>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Initialize config (first run)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.PhyAgentOS:/root/.PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> onboard</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Interactive CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.PhyAgentOS:/root/.PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Long-running gateway (message bus, outbound only, no port mapping needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phyagentos-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.PhyAgentOS:/root/.PhyAgentOS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  phyagentos:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span></span></code></pre></div><hr><h2 id="⚠️-known-limitations" tabindex="-1">⚠️ Known limitations <a class="header-anchor" href="#⚠️-known-limitations" aria-label="Permalink to &quot;⚠️ Known limitations&quot;">​</a></h2><h3 id="_1-managed-forge-skill-runtime-is-not-included" tabindex="-1">1. Managed Forge Skill Runtime is not included <a class="header-anchor" href="#_1-managed-forge-skill-runtime-is-not-included" aria-label="Permalink to &quot;1. Managed Forge Skill Runtime is not included&quot;">​</a></h3><p>The stock image has no Dora CLI or concrete Forge Runtime artifacts. <code>paos skill start</code> therefore is not supported in this image without an explicitly extended image containing Dora CLI v0.4.1, <code>dora-message</code> v0.7.0, and the selected Skill&#39;s platform dependencies. Agent-only and message-channel use does not require Dora.</p><h3 id="_2-container-runs-as-root" tabindex="-1">2. Container runs as root <a class="header-anchor" href="#_2-container-runs-as-root" aria-label="Permalink to &quot;2. Container runs as root&quot;">​</a></h3><p>To stay consistent with the <code>~/.PhyAgentOS:/root/.PhyAgentOS</code> volume-mount convention, the image runs as root by default. For production hardening, consider adding a non-root user and a healthcheck later.</p><h3 id="_3-no-gpu-support" tabindex="-1">3. No GPU support <a class="header-anchor" href="#_3-no-gpu-support" aria-label="Permalink to &quot;3. No GPU support&quot;">​</a></h3><p>This is a CPU image and does not support Isaac Sim / BEHAVIOR-1K or other CUDA-based simulation. For GPU, switch the base image to <code>nvidia/cuda</code> and run with <code>--gpus all</code>.</p><hr><h2 id="🧯-troubleshooting" tabindex="-1">🧯 Troubleshooting <a class="header-anchor" href="#🧯-troubleshooting" aria-label="Permalink to &quot;🧯 Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Symptom</th><th style="text-align:left;">Solution</th></tr></thead><tbody><tr><td style="text-align:left;"><code>docker: command not found</code></td><td style="text-align:left;">Install Docker: <a href="https://docs.docker.com/get-docker" target="_blank" rel="noreferrer">https://docs.docker.com/get-docker</a></td></tr><tr><td style="text-align:left;"><code>Cannot connect to the Docker daemon</code></td><td style="text-align:left;">Start Docker Desktop or <code>sudo systemctl start docker</code></td></tr><tr><td style="text-align:left;">Build OOM / slow</td><td style="text-align:left;">Increase Docker memory; first build downloads deps, later builds use cache</td></tr><tr><td style="text-align:left;"><code>paos agent</code> reports <code>No API key configured</code></td><td style="text-align:left;">Edit <code>~/.PhyAgentOS/config.json</code> and set <code>apiKey</code></td></tr><tr><td style="text-align:left;">Gateway exits immediately after start</td><td style="text-align:left;">Usually a missing API key; confirm with <code>./scripts/install.sh logs</code></td></tr><tr><td style="text-align:left;">Gateway container fails to start</td><td style="text-align:left;"><code>docker rm -f phyagentos-gateway</code> and retry</td></tr></tbody></table><hr><h2 id="📚-related-files" tabindex="-1">📚 Related files <a class="header-anchor" href="#📚-related-files" aria-label="Permalink to &quot;📚 Related files&quot;">​</a></h2><ul><li><a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/Dockerfile" target="_blank" rel="noreferrer"><code>Dockerfile</code></a> — image build definition</li><li><a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/docker-compose.yml" target="_blank" rel="noreferrer"><code>docker-compose.yml</code></a> — Compose orchestration</li><li><a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/.dockerignore" target="_blank" rel="noreferrer"><code>.dockerignore</code></a> — build-ignore rules</li><li><a href="https://github.com/PhyAgentOS/PhyAgentOS-core/blob/main/scripts/install.sh" target="_blank" rel="noreferrer"><code>scripts/install.sh</code></a> — one-click install script</li></ul>`,57)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
